import clsx from 'clsx';
import React, { forwardRef } from 'react';

import { strongCSS } from './Strong.sty.js';
import type { DataTestId } from '../core/types/data-props.js';
import type { StylingProps } from '../core/types/styling-props.js';
import type { WithChildren } from '../core/types/with-children.js';

export interface StrongProps extends WithChildren, StylingProps, DataTestId {}

/**
 * Use the `Strong` component to render text in bold type to emphasize it.
 */
export const Strong = /* @__PURE__ */ forwardRef<HTMLElement, StrongProps>(
  (props, ref) => {
    const {
      children,
      'data-testid': dataTestId,
      className: consumerClassName,
      style: consumerStyle,
      ...remainingProps
    } = props;
    return (
      <strong
        ref={ref}
        data-testid={dataTestId}
        className={clsx(strongCSS, consumerClassName)}
        style={consumerStyle}
        {...remainingProps}
      >
        {children}
      </strong>
    );
  },
);

(Strong as typeof Strong & { displayName: string }).displayName = 'Strong';
